insert into public.area_actions
  (key, area_id, screen_tag, tier, title, why, body, handler, payload, age_bands, boost_personas, featured, sort_order)
values
  ('fit.ten-squats', 'physical', 'ExerciseScreen', 'quick', 'Do 10 squats right now', 'Short bursts of movement add up. Every bit counts toward your day.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 0),
  ('fit.stretch-minute', 'physical', 'ExerciseScreen', 'quick', 'Stand up and stretch for one minute', 'Sitting for a long time makes muscles stiff. Moving resets them.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 1),
  ('fit.walk-15', 'physical', 'ExerciseScreen', 'step', 'Go for a 15-minute walk', 'A brisk walk is real exercise. No gym or gear needed.', null, 'timer', '{"minutes":15}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 2),
  ('fit.strength-plan', 'physical', 'ExerciseScreen', 'step', 'Put two strength sessions in your week', 'Muscle work twice a week is half of the adult guideline, and the half most people skip.', null, 'routine', '{"preset":"physical_starter"}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 3),
  ('fit.kids-how-much', 'physical', 'ExerciseScreen', 'learn', 'How much should kids and teens move?', null, 'Kids and teens aged 6 to 17 need about 60 minutes of activity every day. It doesn''t have to be all at once. Biking to a friend''s, playing tag and shooting hoops all count. Try to include things that make you breathe hard, things that build strength like climbing, and things that make bones strong, like jumping.', 'read', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], false, 4),
  ('fit.adults-enough', 'physical', 'ExerciseScreen', 'learn', 'What ''enough exercise'' actually means', null, 'Adults are advised to get about 150 minutes of moderate activity a week, which is 30 minutes on five days, plus muscle-strengthening work on two days. Moderate means you can talk but not sing. Brisk walking counts. If that feels far off, any amount beats none, and the biggest health gain comes from going from nothing to something.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 5),
  ('fit.move-20', 'physical', 'ExerciseScreen', 'habit', 'Move for 20 minutes today', 'Walking, dancing, sport, chores. It all counts.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 6),
  ('fit.play-outside', 'physical', 'ExerciseScreen', 'habit', 'Play outside for an hour', 'Running around outside is exercise that doesn''t feel like it.', null, 'done', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 7),
  ('food.water-now', 'physical', 'NutritionScreen', 'quick', 'Drink a glass of water now', 'Mild thirst can feel like tiredness or hunger.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 8),
  ('food.add-plant', 'physical', 'NutritionScreen', 'quick', 'Add one fruit or vegetable to your next meal', 'Adding is easier than cutting out, and it crowds out the rest.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 9),
  ('food.half-plate', 'physical', 'NutritionScreen', 'learn', 'The half-plate trick', null, 'An easy way to eat well without counting anything: fill half your plate with fruits and vegetables, a quarter with protein like beans, eggs, fish or chicken, and a quarter with grains, ideally whole grains like brown rice or whole-wheat bread. It works at home, at school and at a restaurant, and nobody has to track a single calorie.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 10),
  ('food.labels', 'physical', 'NutritionScreen', 'learn', 'Reading a nutrition label in 30 seconds', null, 'Start with serving size, because every number on the label is for that amount and packages often hold more than one serving. Then check added sugars and sodium, which most people get too much of, and fiber and protein, which help you stay full. In the percent daily value column, 5% or less is low and 20% or more is high (reviewed 2026).', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 11),
  ('food.water-meals', 'physical', 'NutritionScreen', 'habit', 'Drink water with every meal', 'One simple anchor instead of counting glasses.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 12),
  ('food.breakfast', 'physical', 'NutritionScreen', 'habit', 'Eat breakfast before school', 'It''s hard to focus in class on an empty stomach.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], false, 13),
  ('food.prep-lunch', 'physical', 'NutritionScreen', 'step', 'Prep tomorrow''s lunch tonight', 'Deciding in advance is easier than deciding when you''re hungry.', null, 'done', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 14),
  ('food.help-cook', 'physical', 'NutritionScreen', 'step', 'Help make one meal this week', 'People who help cook tend to try more foods, and it''s a skill for life.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], true, 15),
  ('sleep.charge-outside', 'physical', 'SleepRecoveryScreen', 'quick', 'Charge your phone or tablet outside your bedroom', 'If it''s out of reach, it can''t keep you up.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 16),
  ('sleep.dim-lights', 'physical', 'SleepRecoveryScreen', 'quick', 'Dim the lights an hour before bed', 'Bright light tells your brain it''s still daytime.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 17),
  ('sleep.brain-sleep', 'physical', 'SleepRecoveryScreen', 'learn', 'What your brain does while you sleep', null, 'Sleep isn''t your brain switching off. It''s your brain doing homework. While you sleep, it sorts out what you learned today and stores it so you remember it tomorrow. It also helps you grow and fight off colds. Kids your age need about 9 to 12 hours a night. If mornings are a struggle, an earlier bedtime usually helps more than anything else.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 18),
  ('sleep.teen-marks', 'physical', 'SleepRecoveryScreen', 'learn', 'Why late nights cost you marks', null, 'Teens need about 8 to 10 hours of sleep, and most get less. That matters for school: sleep is when your brain moves what you studied into long-term memory, so staying up late to cram can undo the studying. Your body clock also shifts later in the teen years, which is why falling asleep early feels hard. A fixed wake-up time and less light at night help reset it.', 'read', '{}'::jsonb, array['teen']::text[], '{}'::text[], false, 19),
  ('sleep.sleep-debt', 'physical', 'SleepRecoveryScreen', 'learn', 'Sleep debt doesn''t repay at weekends', null, 'Adults need at least 7 hours a night. Sleeping in on Saturday can make you feel better, but it doesn''t fully undo a week of short nights, and a big weekend lie-in shifts your body clock, which makes Sunday night harder. A consistent wake time, even on days off, does more for sleep quality than any single long night.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 20),
  ('sleep.no-screens', 'physical', 'SleepRecoveryScreen', 'habit', 'No screens in the last hour before bed', 'The light and the scrolling both keep your brain awake.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 21),
  ('sleep.same-bedtime', 'physical', 'SleepRecoveryScreen', 'habit', 'In bed at the same time every night', 'A steady bedtime makes falling asleep easier.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], false, 22),
  ('sleep.same-wake', 'physical', 'SleepRecoveryScreen', 'habit', 'Same wake time every day, weekends too', 'Your wake time sets your body clock more than your bedtime does.', null, 'done', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 23),
  ('sleep.wind-down', 'physical', 'SleepRecoveryScreen', 'step', 'Set a wind-down reminder for tonight', 'A cue at a fixed time beats relying on willpower at midnight.', null, 'reminder', '{"time":"22:30"}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 24),
  ('sleep.pick-bedtime', 'physical', 'SleepRecoveryScreen', 'step', 'Pick a bedtime and tell your family', 'When everyone knows it, it''s easier to stick to.', null, 'done', '{}'::jsonb, array['kid']::text[], '{}'::text[], true, 25),
  ('energy.daylight', 'physical', 'EnergyVitalityScreen', 'quick', 'Step outside for five minutes of daylight', 'Daylight, especially in the morning, helps set your body clock and lift energy.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 26),
  ('energy.move-two', 'physical', 'EnergyVitalityScreen', 'quick', 'Get up and move for two minutes', 'An energy dip after sitting is often your body asking to move.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 27),
  ('energy.afternoon-crash', 'physical', 'EnergyVitalityScreen', 'learn', 'Why you crash in the afternoon', null, 'Most people have a natural energy dip in the early afternoon. It''s part of your body clock, not a sign something is wrong. A heavy lunch, too little sleep and not drinking enough make it worse. A short walk, some daylight or a glass of water usually help more than a sugary snack or a caffeinated drink, which tend to give a quick lift and then a second dip.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 28),
  ('energy.caffeine', 'physical', 'EnergyVitalityScreen', 'learn', 'Caffeine lasts longer than you think', null, 'Caffeine can still be working in your body six hours after you drink it, so an afternoon coffee, energy drink or cola can make it harder to fall asleep, even if you don''t feel wired. Poor sleep then makes you more tired the next day, and the cycle repeats. Energy drinks can carry far more caffeine than a can of soda, and aren''t recommended for kids and teens.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 29),
  ('energy.outside-daily', 'physical', 'EnergyVitalityScreen', 'habit', 'Get outside in daylight today', 'Even a cloudy day is far brighter than indoors.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 30),
  ('energy.checkup', 'physical', 'EnergyVitalityScreen', 'step', 'Check when your last check-up was', 'Check-ups can catch problems before they cause symptoms.', null, 'task', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 31),
  ('energy.water-bottle', 'physical', 'EnergyVitalityScreen', 'step', 'Pack a water bottle for tomorrow', 'If it''s with you, you''ll actually drink it.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], true, 32),
  ('mood.name-it', 'mental', 'WellbeingScreen', 'quick', 'Name how you feel in one word', 'Putting a feeling into words can make it less intense.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 33),
  ('mood.one-good', 'mental', 'WellbeingScreen', 'quick', 'Write down one good thing from today', 'Your brain notices problems automatically. Good things need a nudge.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 34),
  ('mood.all-ok', 'mental', 'WellbeingScreen', 'learn', 'All feelings are OK', null, 'Everyone feels angry, sad, scared or jealous sometimes, even grown-ups. Having a big feeling doesn''t make you bad. What matters is what you do with it: take a breath, say what you feel out loud, or tell someone you trust. Feelings are like weather. Even a big storm passes.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 35),
  ('mood.information', 'mental', 'WellbeingScreen', 'learn', 'Feelings are information, not instructions', null, 'Every feeling is trying to tell you something. Anger often means something feels unfair, sadness that you''ve lost something that mattered, worry that something important is uncertain. You don''t have to act on a feeling, and you don''t have to push it away either. Noticing it, naming it and asking what it''s pointing at is usually enough to take the edge off.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 36),
  ('mood.check-in', 'mental', 'WellbeingScreen', 'habit', 'Check in with how I''m feeling', 'Ten seconds, once a day. Patterns show up fast.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 37),
  ('mood.enjoy-15', 'mental', 'WellbeingScreen', 'step', 'Do something you enjoy for 15 minutes', 'Small, planned bits of enjoyment are one of the most reliable mood lifts.', null, 'timer', '{"minutes":15}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 38),
  ('stress.breathe-4-6', 'mental', 'StressAnxietyScreen', 'quick', 'Breathe in for 4, out for 6, five times', 'A longer out-breath signals your body to calm down.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 39),
  ('stress.grounding', 'mental', 'StressAnxietyScreen', 'quick', 'Try 5-4-3-2-1 grounding', 'Name 5 things you see, 4 you can touch, 3 you hear, 2 you smell, 1 you taste.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 40),
  ('stress.physical-worry', 'mental', 'StressAnxietyScreen', 'learn', 'Why worry feels so physical', null, 'When your brain spots a threat, like a test, an argument or a deadline, it gets your body ready to act: faster heart, quick breathing, tense muscles, a jittery stomach. That''s the stress response, and it''s useful in short bursts. The trouble is it can switch on for things you can''t fight or run from. Slow breathing, moving your body, or naming what''s worrying you all send the ''safe now'' signal back.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 41),
  ('stress.stress-vs-anxiety', 'mental', 'StressAnxietyScreen', 'learn', 'Stress vs. anxiety', null, 'Stress is usually about something specific happening now, like a deadline or a conflict, and eases when it''s over. Anxiety is worry that sticks around even without a clear cause, or that''s much bigger than the situation. Both are common. If worry gets in the way of school, work, sleep or friendships for weeks at a time, that''s a good moment to talk to a doctor or counselor. Anxiety responds well to treatment.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 42),
  ('stress.real-break', 'mental', 'StressAnxietyScreen', 'habit', 'Take one real break today', 'Away from the screen, the desk and the problem.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 43),
  ('stress.worry-to-step', 'mental', 'StressAnxietyScreen', 'step', 'Write down what''s worrying you, then one next step', 'Getting it on paper turns a cloud of worry into something you can act on.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 44),
  ('mind.listen-minute', 'mental', 'SelfCareScreen', 'quick', 'Sit still for one minute and just listen', 'Noticing sounds pulls your attention into right now.', null, 'timer', '{"minutes":1}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 45),
  ('mind.slow-snack', 'mental', 'SelfCareScreen', 'quick', 'Eat your next snack slowly, noticing the taste', 'Anything done with full attention is mindfulness practice.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 46),
  ('mind.what-it-is', 'mental', 'SelfCareScreen', 'learn', 'What mindfulness actually is', null, 'Mindfulness just means paying attention to what''s happening right now, on purpose, without judging it. You don''t need to empty your mind. Minds wander, that''s what they do. The practice is noticing you''ve drifted and gently coming back. Even a minute of this, done most days, can make it easier to stay calm when things get busy.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 47),
  ('mind.mindful-minute', 'mental', 'SelfCareScreen', 'habit', 'Take a mindful minute', 'Short and daily beats long and rare.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 48),
  ('mind.guided-5', 'mental', 'SelfCareScreen', 'step', 'Try a 5-minute guided meditation', 'Free, short, and someone else does the guiding.', null, 'link', '{"url":"https://www.uclahealth.org/uclamindful/guided-meditations"}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 49),
  ('mind.body-scan', 'mental', 'SelfCareScreen', 'step', 'Do a body scan before bed', 'Notice each part of your body, from your toes to your head.', null, 'timer', '{"minutes":5}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], false, 50),
  ('support.save-988', 'mental', 'TherapySupportScreen', 'quick', 'Save 988 in your phone', 'Call or text 988 any time, day or night, if you''re struggling or worried about someone. Free and confidential (US).', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 51),
  ('support.one-person', 'mental', 'TherapySupportScreen', 'quick', 'Think of one person you could talk to if things got hard', 'Knowing who, before you need them, makes reaching out easier.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 52),
  ('support.brave-to-ask', 'mental', 'TherapySupportScreen', 'learn', 'It''s brave to ask for help', null, 'When something is really bothering you, at home, at school, online or inside your head, telling a grown-up you trust is one of the bravest things you can do. That might be a parent, a teacher, a school counselor, a coach or a relative. You don''t have to have the right words. ''Can I talk to you about something?'' is enough.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 53),
  ('support.what-therapy-is', 'mental', 'TherapySupportScreen', 'learn', 'What therapy is actually like', null, 'Therapy is a regular conversation with a trained professional whose whole job is helping you understand what''s going on and find ways to handle it. It isn''t only for a crisis. Lots of people go for stress, relationships, grief or feeling stuck. The first session is mostly getting to know each other. If the first therapist isn''t a good fit, trying another is normal, not failure.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 54),
  ('support.check-trusted', 'mental', 'TherapySupportScreen', 'habit', 'Check in with someone I trust', 'Support works best as a habit, not an emergency.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 55),
  ('support.two-adults', 'mental', 'TherapySupportScreen', 'step', 'Write down two grown-ups you trust', 'So you know exactly who to go to.', null, 'done', '{}'::jsonb, array['kid']::text[], '{}'::text[], true, 56),
  ('support.school-counselor', 'mental', 'TherapySupportScreen', 'step', 'Find out who your school counselor is', 'Talking to them is free, and it''s what they''re there for.', null, 'done', '{}'::jsonb, array['teen']::text[], '{}'::text[], true, 57),
  ('support.what-covered', 'mental', 'TherapySupportScreen', 'step', 'Find out what counseling your work, school or insurance covers', 'Many people have free sessions available and never use them.', null, 'task', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 58),
  ('rel.say-hi', 'social', 'RelationshipsScreen', 'quick', 'Send someone a message just to say hi', 'Small check-ins keep relationships warm between big moments.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 59),
  ('rel.appreciate', 'social', 'RelationshipsScreen', 'quick', 'Tell someone one specific thing you appreciate about them', 'Specific beats general. ''Thanks for waiting for me'' lands harder than ''you''re great''.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 60),
  ('rel.good-friend', 'social', 'RelationshipsScreen', 'learn', 'How to be a good friend', null, 'Good friends listen, take turns, keep promises and stick up for each other. Everyone has fallings-out sometimes. Saying sorry when you''ve hurt someone, and meaning it, fixes more than most people expect. And a good friend is someone who makes you feel good about yourself, not worse.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 61),
  ('rel.small-moments', 'social', 'RelationshipsScreen', 'learn', 'Small moments matter more than big ones', null, 'Strong relationships are built less by grand gestures and more by small everyday moments: noticing when someone wants your attention and turning toward them by looking up, answering, or asking a question. Researchers who study couples, friends and families keep finding the same thing. People who respond to these little bids for connection feel closer over time.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 62),
  ('rel.healthy', 'social', 'RelationshipsScreen', 'learn', 'What healthy relationships have in common', null, 'Respect, honesty, trust and being able to disagree safely. In a healthy relationship, whether friends, family or dating, you can say no without fear, have your own friends and time, and aren''t checked on or controlled. Jealousy that turns into rules about who you can see, or someone reading your phone, isn''t a sign of love. If something feels off, talking to someone you trust is a good first step.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 63),
  ('rel.real-convo', 'social', 'RelationshipsScreen', 'habit', 'Have one real conversation today', 'Not about logistics. About how someone actually is.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 64),
  ('rel.plan-time', 'social', 'RelationshipsScreen', 'step', 'Plan time with someone you care about this week', 'Good intentions become plans only when there''s a day attached.', null, 'task', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 65),
  ('net.hello-new', 'social', 'NetworkScreen', 'quick', 'Say hello to a neighbor or classmate you don''t usually talk to', 'Every close friend was once someone you didn''t know.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 66),
  ('net.reconnect', 'social', 'NetworkScreen', 'quick', 'Message someone you haven''t talked to in a while', 'Old connections are easier to warm up than new ones are to start.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 67),
  ('net.weak-ties', 'social', 'NetworkScreen', 'learn', 'Why people you barely know matter', null, 'Your close friends tend to know the same people and hear about the same things you do. The people you know a little, like a neighbor, a teammate, or someone from a class or club, connect you to different circles. That''s why new opportunities, from a job lead to a new hobby group, often come through acquaintances rather than best friends.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 68),
  ('net.talk-new', 'social', 'NetworkScreen', 'habit', 'Talk to someone new', 'One new name a week adds up to a lot by the end of the year.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 69),
  ('net.club', 'social', 'NetworkScreen', 'step', 'Find one club, team or group to try', 'Doing something together is the easiest way to make friends.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], true, 70),
  ('net.local-group', 'social', 'NetworkScreen', 'step', 'Find one local group or volunteer opportunity', 'Shared activity builds connection faster than small talk.', null, 'task', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 71),
  ('talk.follow-up', 'social', 'CommunicationScreen', 'quick', 'In your next conversation, ask one follow-up question', 'Follow-up questions show you''re actually listening.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 72),
  ('talk.i-feel', 'social', 'CommunicationScreen', 'quick', 'Rewrite one complaint as an ''I feel… when… because…'' sentence', 'It turns an accusation into something the other person can hear.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 73),
  ('talk.i-statements', 'social', 'CommunicationScreen', 'learn', 'How ''I'' statements work', null, '''You never listen'' starts a fight. ''I feel ignored when I''m interrupted, because what I''m saying matters to me'' starts a conversation. Talking about your own feelings and what happened, instead of labeling the other person, makes people less defensive, so they''re more likely to actually hear you. It feels awkward at first. It gets easier.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 74),
  ('talk.boundaries', 'social', 'CommunicationScreen', 'learn', 'Boundaries are about you, not them', null, 'A boundary is a limit on what you will do, not a rule for what someone else must do. ''You can''t yell at me'' is hard to enforce. ''If the yelling starts, I''ll leave the room and we can talk later'' is completely in your control. Clear, calm and followed through: that''s what makes a boundary work.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 75),
  ('talk.no-interrupt', 'social', 'CommunicationScreen', 'habit', 'Listen without interrupting in one conversation', 'Harder than it sounds. Worth it every time.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 76),
  ('talk.say-it', 'social', 'CommunicationScreen', 'step', 'Use an ''I feel'' sentence with someone today', 'Telling people how you feel helps them understand you.', null, 'done', '{}'::jsonb, array['kid']::text[], '{}'::text[], true, 77),
  ('talk.avoided-talk', 'social', 'CommunicationScreen', 'step', 'Plan how you''ll say the thing you''ve been avoiding', 'Writing the first sentence down makes the conversation far easier to start.', null, 'done', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 78),
  ('socialh.catch-up', 'social', 'SocialHealthScreen', 'quick', 'Text or call a friend just to catch up', 'No reason needed. That''s the point.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 79),
  ('socialh.phone-away', 'social', 'SocialHealthScreen', 'quick', 'Put your phone away during your next meal with someone', 'Even a phone face-down on the table makes conversations shallower.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 80),
  ('socialh.loneliness', 'social', 'SocialHealthScreen', 'learn', 'Loneliness is a signal, not a flaw', null, 'Feeling lonely is your brain''s way of saying you need more connection, the way hunger tells you to eat. It happens to everyone, including people surrounded by others, because it''s about feeling close, not how many people are around. The fix usually starts small: one conversation, one shared activity, one person you see regularly.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 81),
  ('socialh.in-person', 'social', 'SocialHealthScreen', 'habit', 'Spend time with someone in person', 'Messages help. Being there helps more.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 82),
  ('socialh.hangout', 'social', 'SocialHealthScreen', 'step', 'Plan one in-person hangout this week', 'A plan with a day on it actually happens.', null, 'task', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 83),
  ('income.where-from', 'financial', 'IncomeEarningsScreen', 'quick', 'Write down where your money comes from', 'Allowance, gifts, a paycheck, side work. Seeing it all is the first step.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 84),
  ('income.where-money-comes', 'financial', 'IncomeEarningsScreen', 'learn', 'Where money comes from', null, 'Money usually comes from doing work that someone else values: making something, fixing something, helping with something, or teaching something. Grown-ups get paid for their jobs. Kids can earn too, by doing extra chores, helping neighbors, or selling something they made. The more useful or rare the thing you can do, the more people will pay for it.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 85),
  ('income.gross-net', 'financial', 'IncomeEarningsScreen', 'learn', 'Gross pay vs. take-home pay', null, 'The pay you''re offered, called gross pay, isn''t what lands in your account. Before you get it, money comes out for taxes, and often for things like health insurance or retirement savings. What''s left is net, or take-home, pay. That''s the number that actually pays the bills, so it''s the one to plan with. Your first payslip shows where each deduction goes.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 86),
  ('income.second-stream', 'financial', 'IncomeEarningsScreen', 'learn', 'Why a second income stream matters', null, 'If all your money comes from one place, losing it means losing everything at once. A second source, like freelance work, a side project, or a skill you can sell, spreads that risk out. It doesn''t need to be big to matter. Even a small, steady amount can cover a bill, build savings, or become a fallback if your main income stops.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 87),
  ('income.log-earned', 'financial', 'IncomeEarningsScreen', 'habit', 'Log money I earned this week', 'Tracking income is how you notice it growing, or not.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 88),
  ('income.extra-job', 'financial', 'IncomeEarningsScreen', 'step', 'Ask a grown-up about one extra job you could do to earn money', 'Earning your own money feels different from being given it.', null, 'done', '{}'::jsonb, array['kid']::text[], '{}'::text[], true, 89),
  ('income.three-ways', 'financial', 'IncomeEarningsScreen', 'step', 'List three ways you could earn money at your age', 'Babysitting, tutoring, pet-sitting, yard work. There are more options than it seems.', null, 'done', '{}'::jsonb, array['teen']::text[], '{}'::text[], true, 90),
  ('income.payslip', 'financial', 'IncomeEarningsScreen', 'step', 'Check your last payslip line by line', 'Mistakes happen, and every deduction should be one you recognize.', null, 'done', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 91),
  ('budget.count-money', 'financial', 'BudgetSpendingScreen', 'quick', 'Count how much money you have saved', 'Knowing your number makes every choice clearer.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], true, 92),
  ('budget.check-balance', 'financial', 'BudgetSpendingScreen', 'quick', 'Check your account balance right now', 'Most overspending happens when we''re guessing.', null, 'done', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 93),
  ('budget.needs-wants', 'financial', 'BudgetSpendingScreen', 'learn', 'Needs vs. wants', null, 'A need is something you can''t do without: food, a home, clothes that fit. A want is something nice to have, like a new game, candy or the latest sneakers. Wants aren''t bad! But when money is limited, needs come first. Before buying something, ask: do I need this, or do I want it? And will I still want it next week?', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 94),
  ('budget.wait-24', 'financial', 'BudgetSpendingScreen', 'learn', 'The 24-hour rule', null, 'Before any purchase you didn''t plan, wait 24 hours. If you still want it tomorrow, it''s probably a real want. If you''ve forgotten about it, you just saved money. Stores and apps are designed to make buying fast and emotional, with countdown timers, ''only 2 left'' and one-tap checkout. A pause is the simplest defense there is.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 95),
  ('budget.split', 'financial', 'BudgetSpendingScreen', 'learn', 'A simple way to split your money', null, 'One common starting point is 50/30/20: about half of take-home pay for needs like rent, food and bills, about a third for wants, and a fifth for savings or paying down debt (reviewed 2026). It''s a rule of thumb, not a law. In expensive cities, needs often take more. The point is to decide the split on purpose instead of finding out at the end of the month.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 96),
  ('budget.wait-a-day', 'financial', 'BudgetSpendingScreen', 'habit', 'Wait a day before buying something I didn''t plan', 'The want that survives a night''s sleep is the real one.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 97),
  ('budget.subscriptions', 'financial', 'BudgetSpendingScreen', 'step', 'List every subscription you pay for', 'Most people find at least one they forgot about.', null, 'task', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 98),
  ('save.jar', 'financial', 'SavingsInvestingScreen', 'quick', 'Put some of your next money in your savings jar', 'Saving first means you don''t spend it by accident.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], true, 99),
  ('save.move-small', 'financial', 'SavingsInvestingScreen', 'quick', 'Move a small amount into savings today', 'The habit matters more than the amount.', null, 'done', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 100),
  ('save.three-jars', 'financial', 'SavingsInvestingScreen', 'learn', 'Save, spend, share', null, 'One simple way to handle money: split it into three jars. Spend is for things you want now. Save is for something bigger later, so you don''t spend it by accident. Share is for giving to someone or something you care about. Even putting a little in the Save jar each time adds up faster than you''d think.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 101),
  ('save.compound', 'financial', 'SavingsInvestingScreen', 'learn', 'How compound interest works', null, 'When savings earn interest, next year you earn interest on the interest too. Imagine putting away $100 that grows 5% a year: after one year it''s $105, and in the second year you earn interest on $105, not $100. Over decades that snowball gets big, which is why starting early matters more than starting with a lot.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 102),
  ('save.emergency-fund', 'financial', 'SavingsInvestingScreen', 'learn', 'What an emergency fund is for', null, 'An emergency fund is money set aside only for surprises: a car repair, a medical bill, losing a job. Without one, an emergency often goes on a credit card and turns into debt. Many guides suggest working toward three to six months of essential expenses (reviewed 2026), but even a small starting cushion changes how a surprise bill feels. It''s usually kept somewhere separate and easy to reach.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 103),
  ('save.diversification', 'financial', 'SavingsInvestingScreen', 'learn', 'What diversification means', null, 'Owning shares in one company means your money rides on that one company. Owning a little of hundreds, which is what an index fund does, means one company failing barely moves your total. That spread is diversification. It doesn''t remove risk: when the whole market falls, a diversified fund falls too. It removes the risk of betting everything on being right about one thing.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 104),
  ('save.fdic', 'financial', 'SavingsInvestingScreen', 'learn', 'Savings accounts are insured, up to a point', null, 'In the US, money in a bank covered by the FDIC is insured up to $250,000 per depositor, per bank, per account type (reviewed 2026). If the bank fails, you get it back. Investments like stocks and funds aren''t insured this way, and their value can go down. Banks that are covered say ''Member FDIC'', and credit unions say NCUA.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 105),
  ('save.save-something', 'financial', 'SavingsInvestingScreen', 'habit', 'Put something into savings', 'Any amount. The streak is the point.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 106),
  ('save.make-jars', 'financial', 'SavingsInvestingScreen', 'step', 'Make three jars: Spend, Save, Share', 'Label them, and split any money you get between them.', null, 'done', '{}'::jsonb, array['kid']::text[], '{}'::text[], true, 107),
  ('save.save-goal', 'financial', 'SavingsInvestingScreen', 'step', 'Pick one thing to save for and write down the price', 'A goal with a number on it is much easier to save toward.', null, 'done', '{}'::jsonb, array['teen']::text[], '{}'::text[], true, 108),
  ('save.employer-match', 'financial', 'SavingsInvestingScreen', 'step', 'Find out if your employer matches retirement savings', 'Some employers add money when you contribute. Not knowing is how people miss it.', null, 'task', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 109),
  ('debt.pay-back', 'financial', 'DebtCreditScreen', 'quick', 'Pay back anything you''ve borrowed from a friend', 'Paying back on time is how people learn they can trust you.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], true, 110),
  ('debt.credit-report', 'financial', 'DebtCreditScreen', 'quick', 'Check your credit report for free', 'Free weekly reports from all three bureaus. Errors happen, and you can dispute them.', null, 'link', '{"url":"https://www.annualcreditreport.com"}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 111),
  ('debt.borrowing', 'financial', 'DebtCreditScreen', 'learn', 'What borrowing means', null, 'Borrowing means using something that isn''t yours yet and promising to give it back. If a friend lends you some money, you owe them that money back. Grown-ups borrow from banks too, but banks charge extra for it, called interest, so you pay back more than you borrowed. That''s why people try to borrow only when they really need to.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 112),
  ('debt.credit-score', 'financial', 'DebtCreditScreen', 'learn', 'How credit scores work', null, 'A credit score is a number, usually between 300 and 850, that tells lenders how reliably you''ve paid back what you borrowed. It''s built from your history: paying on time, how much of your available credit you use, how long you''ve had credit, and how often you apply for more. You can''t build one until you have credit in your name, but understanding it now means you won''t damage it by accident later.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 113),
  ('debt.minimums', 'financial', 'DebtCreditScreen', 'learn', 'Why minimum payments cost so much', null, 'Credit cards often charge interest above 20% a year (reviewed 2026). Paying only the minimum keeps the account in good standing, but much of that payment goes to interest, so the balance barely shrinks, and a few hundred dollars can take years to clear. Anything paid above the minimum goes straight to the balance and shortens that time a lot.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 114),
  ('debt.avalanche-snowball', 'financial', 'DebtCreditScreen', 'learn', 'Avalanche vs. snowball', null, 'Two common ways to pay off several debts. Avalanche: pay minimums on everything, then put every extra dollar on the highest interest rate first. It costs the least overall. Snowball: put extra on the smallest balance first. You clear whole debts sooner, which keeps many people motivated. The math favors avalanche; the one that works is the one you''ll stick to.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 115),
  ('debt.on-time', 'financial', 'DebtCreditScreen', 'habit', 'Pay back what I owe on time', 'Friends, family or a lender. On time is the whole game.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 116),
  ('debt.ask-credit', 'financial', 'DebtCreditScreen', 'step', 'Ask a parent or guardian how credit works in real life', 'Real examples teach more than any definition.', null, 'done', '{}'::jsonb, array['teen']::text[], '{}'::text[], false, 117),
  ('debt.list-debts', 'financial', 'DebtCreditScreen', 'step', 'List every debt with its balance and interest rate', 'You can''t choose a payoff order until you can see them side by side.', null, 'done', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 118),
  ('hobby.fun-10', 'creative', 'HobbiesScreen', 'quick', 'Spend 10 minutes on something just for fun', 'No goal, no score. Just because you like it.', null, 'timer', '{"minutes":10}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 119),
  ('hobby.always-wanted', 'creative', 'HobbiesScreen', 'quick', 'Write down three things you''ve always wanted to try', 'A list turns ''someday'' into options.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 120),
  ('hobby.why-hobbies', 'creative', 'HobbiesScreen', 'learn', 'Why hobbies matter more than they seem', null, 'A hobby is one of the few things you do purely because you like it: no grades, no pay, no one to impress. That''s exactly why it helps. It gives your mind a break from pressure, builds skills that surprise you later, and connects you with people who like the same thing. You don''t have to be good at it. That''s not the point.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 121),
  ('hobby.hobby-today', 'creative', 'HobbiesScreen', 'habit', 'Do my hobby today', 'Even 10 minutes keeps it alive.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 122),
  ('hobby.new-thing', 'creative', 'HobbiesScreen', 'step', 'Try one new thing this week', 'You can''t know you''d love something until you''ve tried it.', null, 'task', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 123),
  ('art.draw-5', 'creative', 'ArtMusicScreen', 'quick', 'Draw anything for five minutes', 'Quantity comes before quality. Just start.', null, 'timer', '{"minutes":5}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 124),
  ('art.one-song', 'creative', 'ArtMusicScreen', 'quick', 'Listen to one song all the way through, doing nothing else', 'Really listening is a skill, and it''s where making music starts.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 125),
  ('art.practice-talent', 'creative', 'ArtMusicScreen', 'learn', 'Practice beats talent', null, 'Most people who seem naturally talented just practiced more, often in ways you didn''t see. Short, focused practice, like 15 minutes working on one specific thing, beats hours of noodling around. Pick one small skill, like a chord change or drawing hands, and repeat it until it feels easier. Then pick the next one.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 126),
  ('art.practice', 'creative', 'ArtMusicScreen', 'habit', 'Practice my art or instrument', 'A little, often. That''s how every artist got good.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 127),
  ('art.finish-small', 'creative', 'ArtMusicScreen', 'step', 'Make something small and finish it', 'Finished and imperfect teaches more than perfect and abandoned.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 128),
  ('media.one-idea', 'creative', 'ContentMediaScreen', 'quick', 'Write down one idea for something you''d like to make', 'Ideas vanish fast. Catch them when they show up.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 129),
  ('media.study-creator', 'creative', 'ContentMediaScreen', 'quick', 'Look at how one creator you like structures their work', 'Notice how they start, what they cut, how they end.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 130),
  ('media.share-safe', 'creative', 'ContentMediaScreen', 'learn', 'Stay safe when you share online', null, 'Before you post anything, check it doesn''t show your full name, school, address, or anything that shows where you are right now, like a street sign or your uniform. Keep accounts private and only accept people you know in real life. If anyone online makes you uncomfortable or asks for photos, stop replying and tell an adult you trust. That''s never overreacting.', 'read', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], false, 131),
  ('media.consistency', 'creative', 'ContentMediaScreen', 'learn', 'Consistency beats going viral', null, 'Most creators who grow do it by posting regularly for a long time, not by one post blowing up. A schedule you can actually keep, even once a week, builds an audience and your skills at the same time. Every piece is also practice: your hundredth video will be far better than your first, and you only get there by making the first ninety-nine.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 132),
  ('media.make-something', 'creative', 'ContentMediaScreen', 'habit', 'Work on something I''m making', 'Progress, not perfection.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 133),
  ('media.share-family', 'creative', 'ContentMediaScreen', 'step', 'Make something and share it with family or friends first', 'People who know you give the kindest, most useful feedback.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], true, 134),
  ('media.plan-three', 'creative', 'ContentMediaScreen', 'step', 'Plan your next three pieces', 'Knowing what''s next removes the blank-page problem.', null, 'task', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 135),
  ('curious.look-up', 'creative', 'LearningCuriosityScreen', 'quick', 'Look up one thing you''ve always wondered about', 'Curiosity grows when you feed it.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 136),
  ('curious.read-10', 'creative', 'LearningCuriosityScreen', 'quick', 'Read for ten minutes', 'Anything you like. Books, articles, comics all count.', null, 'timer', '{"minutes":10}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 137),
  ('curious.curiosity-sticks', 'creative', 'LearningCuriosityScreen', 'learn', 'Curiosity makes things stick', null, 'You remember things better when you actually want to know the answer. So before you learn something, ask yourself a question about it first, like ''why does that happen?'' or ''how would I explain this?'' Trying to answer before you look it up, even if you get it wrong, makes the real answer stick much better.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 138),
  ('curious.learn-one', 'creative', 'LearningCuriosityScreen', 'habit', 'Learn one new thing today', 'Small facts connect into big understanding.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 139),
  ('curious.explore-month', 'creative', 'LearningCuriosityScreen', 'step', 'Pick a book, course or topic to explore this month', 'A month is long enough to go deep, short enough to finish.', null, 'task', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 140),
  ('career.three-jobs', 'professional', 'CareerExplorationScreen', 'quick', 'Write down three jobs that sound interesting', 'Don''t filter. Just notice what pulls you.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 141),
  ('career.grown-ups-do', 'professional', 'CareerExplorationScreen', 'learn', 'What do grown-ups actually do all day?', null, 'There are thousands of different jobs, and many you''ve never heard of. Someone designs roller coasters, someone tests video games, someone looks after zoo animals, someone builds bridges. A great way to find out what jobs are really like is to ask the grown-ups around you: What do you do all day? What''s the best part? What''s the hardest?', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 142),
  ('career.dont-know-yet', 'professional', 'CareerExplorationScreen', 'learn', 'You don''t need to know what you want yet', null, 'Most people don''t pick a career once and stick to it. They try things, learn what they like and don''t, and adjust. The fastest way to figure it out isn''t thinking harder, it''s small experiments: reading about a job, talking to someone who does it, trying a short version of it. Each one tells you more than any quiz can.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 143),
  ('career.learn-job', 'professional', 'CareerExplorationScreen', 'habit', 'Learn about one job this week', 'Every job you learn about widens what feels possible.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 144),
  ('career.ask-adult-job', 'professional', 'CareerExplorationScreen', 'step', 'Ask a grown-up what their job is really like', 'The best part, the hardest part, and how they got there.', null, 'done', '{}'::jsonb, array['kid']::text[], '{}'::text[], true, 145),
  ('career.wayfinder', 'professional', 'CareerExplorationScreen', 'step', 'Take the Wayfinder to see which paths fit you', 'Built for when you''re not sure what you want.', null, 'screen', '{"screen":"WayfinderScreen"}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 146),
  ('career.ooh', 'professional', 'CareerExplorationScreen', 'step', 'Look up one job in the Occupational Outlook Handbook', 'What the job involves, what training it needs, and whether it''s growing.', null, 'link', '{"url":"https://www.bls.gov/ooh/"}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 147),
  ('skills.quiz-self', 'professional', 'ResearchScreen', 'quick', 'Quiz yourself on something you learned this week', 'Pulling information out of memory strengthens it more than re-reading.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], array['STUDENT']::text[], true, 148),
  ('skills.test-yourself', 'professional', 'ResearchScreen', 'learn', 'Study smarter: test yourself', null, 'Re-reading notes feels productive but doesn''t stick well. What works much better: closing the book and trying to recall what you learned, with flashcards, practice questions, or explaining it out loud. Spreading that practice over several days, instead of cramming the night before, makes it last even longer. These two techniques, retrieval and spacing, are among the best-supported findings in learning research.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], array['STUDENT']::text[], false, 149),
  ('skills.practice-15', 'professional', 'ResearchScreen', 'habit', 'Practice a skill for 15 minutes', 'Fifteen minutes a day is over 90 hours a year.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 150),
  ('skills.pick-skill', 'professional', 'ResearchScreen', 'step', 'Pick one skill to get better at this month', 'One skill, measurably better, beats five skills a little busier.', null, 'task', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 151),
  ('projects.next-step', 'professional', 'ProjectsScreen', 'quick', 'Write the very next step for one project', 'A clear next step is the difference between a project and a wish.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 152),
  ('projects.focus-25', 'professional', 'ProjectsScreen', 'quick', 'Start a 25-minute focus session', 'One block of real focus moves more than a day of half-attention.', null, 'timer', '{"minutes":25}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 153),
  ('projects.finish-small', 'professional', 'ProjectsScreen', 'learn', 'Finish small, then grow', null, 'Big projects stall because the finish line is too far away to feel real. Break it into pieces small enough to finish in one sitting, and decide what ''done'' looks like for each. Finishing something small gives you momentum and something real to show, which is far more motivating than a half-built big thing.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 154),
  ('projects.project-time', 'professional', 'ProjectsScreen', 'habit', 'Work on a project', 'Even a little keeps it moving and keeps it in your head.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 155),
  ('projects.open-workshop', 'professional', 'ProjectsScreen', 'step', 'Open the Workshop and pick one project to move forward', 'Choose one. Momentum comes from focus.', null, 'screen', '{"screen":"ProjectsScreen"}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 156),
  ('venture.problem', 'professional', 'BusinessVenturesScreen', 'quick', 'Write down one problem you''ve noticed people complaining about', 'Every business starts as a problem someone wants solved.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 157),
  ('venture.what-business', 'professional', 'BusinessVenturesScreen', 'learn', 'What is a business?', null, 'A business is a way of making money by solving a problem for people. A lemonade stand solves ''I''m thirsty.'' A dog-walking service solves ''I''m too busy to walk my dog.'' Every business needs three things: something people want, a way to reach them, and a price that covers what it costs to make, with a bit left over. That bit left over is called profit.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 158),
  ('venture.talk-first', 'professional', 'BusinessVenturesScreen', 'learn', 'Talk to customers before you build', null, 'The most common way new businesses fail is building something nobody wants. Before spending money or months building, talk to people who have the problem you want to solve. Ask how they deal with it now and what it costs them, not whether they like your idea, because people are polite. If they''re already paying or struggling to solve it, that''s a real signal.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], array['ENTREPRENEUR', 'BUSINESS']::text[], false, 159),
  ('venture.revenue-profit', 'professional', 'BusinessVenturesScreen', 'learn', 'Revenue isn''t profit', null, 'Revenue is all the money coming in. Profit is what''s left after every cost: materials, tools, fees, your time, and taxes. A business can have lots of revenue and still lose money. Knowing your real cost per sale, before you set a price, is one of the first things worth working out.', 'read', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], array['ENTREPRENEUR', 'BUSINESS']::text[], false, 160),
  ('venture.move-task', 'professional', 'BusinessVenturesScreen', 'habit', 'Move one venture task forward', 'Ventures are built in small, steady steps.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 161),
  ('venture.people-pay', 'professional', 'BusinessVenturesScreen', 'step', 'Think of something you could make or do that people would pay for', 'That''s how every business begins.', null, 'done', '{}'::jsonb, array['kid']::text[], '{}'::text[], true, 162),
  ('venture.three-people', 'professional', 'BusinessVenturesScreen', 'step', 'Talk to three people who have the problem you want to solve', 'Three conversations will tell you more than a month of planning.', null, 'task', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], array['ENTREPRENEUR', 'BUSINESS']::text[], true, 163),
  ('purpose.three-matter', 'spiritual', 'PurposeValuesScreen', 'quick', 'Write down three things that matter most to you', 'Naming them is the first step to living by them.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 164),
  ('purpose.compass', 'spiritual', 'PurposeValuesScreen', 'learn', 'Values are a compass, not a destination', null, 'A goal is something you finish, like passing a test. A value is a direction you keep choosing, like being kind, curious or brave. You never ''complete'' it. When you know your values, hard choices get easier: you ask which option looks more like the person you want to be. And on days a goal goes wrong, you can still live a value.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 165),
  ('purpose.live-value', 'spiritual', 'PurposeValuesScreen', 'habit', 'Do one thing that matches my values', 'Values show up in actions, not intentions.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 166),
  ('purpose.top-value', 'spiritual', 'PurposeValuesScreen', 'step', 'Pick your top value and one way to live it this week', 'A value with a plan becomes a habit.', null, 'task', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 167),
  ('purpose.mission', 'spiritual', 'PurposeValuesScreen', 'step', 'Write your personal mission in one sentence', 'Short enough to remember, clear enough to decide with.', null, 'done', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 168),
  ('reflect.quiet-minute', 'spiritual', 'ReflectionPrayerScreen', 'quick', 'Take one quiet minute to reflect, pray or breathe', 'One minute of stillness resets more than you''d expect.', null, 'timer', '{"minutes":1}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 169),
  ('reflect.grateful', 'spiritual', 'ReflectionPrayerScreen', 'quick', 'Write down one thing you''re grateful for', 'Specific gratitude beats general. Name the thing.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 170),
  ('reflect.why-reflect', 'spiritual', 'ReflectionPrayerScreen', 'learn', 'Why reflection helps', null, 'Taking a few quiet minutes to look back on your day, through prayer, meditation, journaling or just sitting still, helps you notice what went well, what you''d do differently, and what you care about. People of many faiths, and of none, have practiced some form of this for thousands of years. It works best as a small daily habit rather than a big occasional one.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 171),
  ('reflect.reflect-daily', 'spiritual', 'ReflectionPrayerScreen', 'habit', 'Reflect, pray or meditate today', 'Whatever form fits you. Daily is what matters.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 172),
  ('reflect.went-well', 'spiritual', 'ReflectionPrayerScreen', 'step', 'Answer tonight: what went well today, and why?', 'The ''why'' is the part that teaches you something.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 173),
  ('wisdom.quote', 'spiritual', 'PhilosophyWisdomScreen', 'quick', 'Read one short quote and decide if you agree', 'Disagreeing with a thinker is still thinking.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 174),
  ('wisdom.big-questions', 'spiritual', 'PhilosophyWisdomScreen', 'learn', 'Big questions are allowed', null, 'Why are we here? What makes something fair? Is it ever OK to break a rule? These are philosophy questions, and you''re never too young to wonder about them. Philosophers don''t just find answers. They practice asking good questions, listening to different views, and changing their mind when there''s a better reason. You can do that too, starting with any question that makes you curious.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 175),
  ('wisdom.control', 'spiritual', 'PhilosophyWisdomScreen', 'learn', 'What''s in your control, and what isn''t', null, 'The Stoic philosopher Epictetus, who began life enslaved, taught one idea that still helps people today: split what''s in your control from what isn''t. Your effort, your words and how you respond are yours. Other people''s opinions, the weather and the past are not. Putting your energy only into the first list is a surprisingly powerful way to worry less.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 176),
  ('wisdom.big-question', 'spiritual', 'PhilosophyWisdomScreen', 'habit', 'Think about one big question', 'Five minutes of real thinking, no phone.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 177),
  ('wisdom.hard-lesson', 'spiritual', 'PhilosophyWisdomScreen', 'step', 'Write down one lesson you learned the hard way', 'Your own experience is wisdom too. Write it down so you keep it.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 178),
  ('wisdom.classic', 'spiritual', 'PhilosophyWisdomScreen', 'step', 'Read one chapter of a philosophy classic', 'Marcus Aurelius wrote Meditations as a private notebook. It''s free.', null, 'link', '{"url":"https://www.gutenberg.org/ebooks/2680"}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 179),
  ('faith.kind-thing', 'spiritual', 'CommunityFaithScreen', 'quick', 'Do one small kind thing for someone today', 'Small kindnesses ripple further than you''ll see.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 180),
  ('faith.helping-helps', 'spiritual', 'CommunityFaithScreen', 'learn', 'Helping others helps you too', null, 'Volunteering and small acts of kindness are good for the people you help, and research keeps finding they''re good for the helper too, linked to better mood and a stronger sense of purpose. It doesn''t have to be big or organized. Helping a neighbor, joining a service day with your school or faith community, or checking on someone who''s alone all count.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 181),
  ('faith.kind-helpful', 'spiritual', 'CommunityFaithScreen', 'habit', 'Do something kind or helpful', 'One a day. They add up.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 182),
  ('faith.help-unasked', 'spiritual', 'CommunityFaithScreen', 'step', 'Help out at home or school without being asked', 'Noticing what needs doing is a superpower.', null, 'done', '{}'::jsonb, array['kid']::text[], '{}'::text[], true, 183),
  ('faith.volunteer', 'spiritual', 'CommunityFaithScreen', 'step', 'Find one volunteer opportunity near you', 'Giving an afternoon connects you to people and to purpose.', null, 'task', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 184),
  ('faith.show-up', 'spiritual', 'CommunityFaithScreen', 'step', 'If you''re part of a faith or community group, plan to show up this week', 'Belonging grows from showing up regularly.', null, 'task', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 185),
  ('privacy.private', 'digital', 'PrivacyScreen', 'quick', 'Check that your accounts are set to private', 'Public by default is common. Private by choice is safer.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 186),
  ('privacy.location-off', 'digital', 'PrivacyScreen', 'quick', 'Turn off location for one app that doesn''t need it', 'Many apps ask for location they don''t need to work.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 187),
  ('privacy.never-share', 'digital', 'PrivacyScreen', 'learn', 'Never share these online', null, 'Some things should stay offline: your full name together with your school, your home address, your phone number, passwords, and photos that show where you are right now. People online aren''t always who they say they are. If someone you only know online asks for personal information, photos, or to keep a secret, stop talking to them and tell a trusted adult.', 'read', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], false, 188),
  ('privacy.data-product', 'digital', 'PrivacyScreen', 'learn', 'When it''s free, your data often pays', null, 'When an app or site is free, it often makes money from what it learns about you, like what you click, where you go and who you talk to, usually to sell ads. That''s not always bad, but it''s worth knowing. Checking privacy settings, turning off location for apps that don''t need it, and thinking twice before sharing personal details keeps more of your life yours.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 189),
  ('privacy.think-share', 'digital', 'PrivacyScreen', 'habit', 'Think before I share', 'Once it''s online, it''s hard to take back.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 190),
  ('privacy.breach', 'digital', 'PrivacyScreen', 'step', 'Check if your email has been in a data breach', 'If it has, change that password anywhere you reused it.', null, 'link', '{"url":"https://haveibeenpwned.com"}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 191),
  ('privacy.location-review', 'digital', 'PrivacyScreen', 'step', 'Review which apps can see your location', 'Settings, then Privacy, then Location. Two minutes, big difference.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 192),
  ('security.update-now', 'digital', 'SecurityScreen', 'quick', 'Update your phone or computer now', 'Updates fix security holes attackers already know about.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 193),
  ('security.passwords-secret', 'digital', 'SecurityScreen', 'learn', 'Keep passwords secret, even from friends', null, 'Your password is like the key to your house. You wouldn''t hand copies to friends, even best friends. Friendships change, and someone with your password can post as you or read your messages. The only people who should know your passwords are you and a parent or guardian who helps keep you safe online.', 'read', '{}'::jsonb, array['kid']::text[], '{}'::text[], false, 194),
  ('security.strong-password', 'digital', 'SecurityScreen', 'learn', 'What makes a strong password', null, 'Length beats complexity. A long passphrase made of four or more random words is easier to remember and harder to crack than a short jumble like ''P@ss1''. The most important rule is never reusing a password: when one site gets breached, attackers try that same password everywhere else. A password manager remembers them all so you don''t have to.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 195),
  ('security.two-step', 'digital', 'SecurityScreen', 'learn', 'Two-step login stops most account takeovers', null, 'Two-factor authentication means logging in needs something you know, your password, and something you have, like your phone or a security key. Even if your password leaks, someone without your phone can''t get in. An authenticator app is safer than text-message codes, but any second step is far better than none. Email is the place to start, since it can reset everything else.', 'read', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 196),
  ('security.lock-devices', 'digital', 'SecurityScreen', 'habit', 'Lock my devices when I step away', 'An unlocked phone is an open door.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 197),
  ('security.enable-2fa', 'digital', 'SecurityScreen', 'step', 'Turn on two-step login for your email', 'Your email can reset every other account you have.', null, 'done', '{}'::jsonb, array['teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 198),
  ('security.password-manager', 'digital', 'SecurityScreen', 'step', 'Set up a password manager', 'Free options exist. One strong password protects all the others.', null, 'link', '{"url":"https://bitwarden.com"}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 199),
  ('focus.phone-away-30', 'digital', 'ScreenTimeFocusScreen', 'quick', 'Put your phone in another room for 30 minutes', 'Out of sight really is out of mind.', null, 'timer', '{"minutes":30}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 200),
  ('focus.notif-off', 'digital', 'ScreenTimeFocusScreen', 'quick', 'Turn off notifications for one app', 'Most notifications are there for the app''s benefit, not yours.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 201),
  ('focus.notifications', 'digital', 'ScreenTimeFocusScreen', 'learn', 'Why notifications break focus', null, 'Every buzz or banner pulls your attention away, and getting back into deep focus can take several minutes, not seconds. Many apps are designed to keep you checking, with streaks, endless feeds and red badges. Turning off notifications you don''t need, and putting your phone out of sight while you work or study, is one of the easiest ways to get more done in less time.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 202),
  ('focus.phone-free', 'digital', 'ScreenTimeFocusScreen', 'habit', 'Phone-free while working or studying', 'Focus is a skill. Every session strengthens it.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 203),
  ('focus.check-screen-time', 'digital', 'ScreenTimeFocusScreen', 'step', 'Check your screen time for last week', 'Most people are surprised. The number is where change starts.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 204),
  ('focus.media-plan', 'digital', 'ScreenTimeFocusScreen', 'step', 'Make a family media plan together', 'Rules everyone agrees on are easier to keep.', null, 'link', '{"url":"https://www.healthychildren.org/English/fmp/Pages/MediaPlan.aspx"}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], false, 205),
  ('tools.delete-five', 'digital', 'ToolsSystemsScreen', 'quick', 'Delete five apps or files you don''t use', 'Less clutter, less distraction, more space.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 206),
  ('tools.capture-all', 'digital', 'ToolsSystemsScreen', 'quick', 'Capture everything on your mind right now', 'Two minutes emptying your head, then decide what matters.', null, 'screen', '{"screen":"CaptureInbox"}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 207),
  ('tools.out-of-head', 'digital', 'ToolsSystemsScreen', 'learn', 'Get it out of your head', null, 'Your brain is great at having ideas and bad at holding reminders. Every to-do you''re trying to remember takes up attention. Writing things down in one trusted place, a notes app, a planner, or the Capture button in this app, frees your mind to focus on what you''re doing now. The trick is having just one place, and checking it.', 'read', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 208),
  ('tools.one-place', 'digital', 'ToolsSystemsScreen', 'habit', 'Capture ideas and to-dos in one place', 'One inbox beats five sticky notes.', null, 'done', '{}'::jsonb, array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], '{}'::text[], false, 209),
  ('tools.school-folders', 'digital', 'ToolsSystemsScreen', 'step', 'Organize your schoolwork into folders', 'Finding things fast means less stress before a deadline.', null, 'done', '{}'::jsonb, array['kid', 'teen']::text[], '{}'::text[], true, 210),
  ('tools.automate', 'digital', 'ToolsSystemsScreen', 'step', 'Automate one thing you do every week', 'A bill on autopay or a recurring reminder is time back, forever.', null, 'task', '{}'::jsonb, array['young_adult', 'adult', 'professional']::text[], '{}'::text[], true, 211)
insert into public.area_resources
  (key, area_id, screen_tag, title, description, url, source, kind, cost, age_bands, sort_order)
values
  ('fit.move-your-way', 'physical', 'ExerciseScreen', 'Move Your Way', 'How much activity you need, by age, with ideas to fit it in.', 'https://odphp.health.gov/moveyourway', 'US Dept. of Health', 'guide', 'free', array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], 0),
  ('fit.cdc-activity', 'physical', 'ExerciseScreen', 'CDC: Physical Activity Guidelines', 'Official guidelines for kids, teens and adults.', 'https://www.cdc.gov/physical-activity-basics/guidelines/index.html', 'CDC', 'guide', 'free', array['teen', 'young_adult', 'adult', 'professional']::text[], 1),
  ('fit.couch-5k', 'physical', 'ExerciseScreen', 'NHS Couch to 5K', 'A free 9-week plan from not running to running 5K.', 'https://www.nhs.uk/live-well/exercise/running-and-aerobic-exercises/get-running-with-couch-to-5k/', 'NHS', 'course', 'free', array['teen', 'young_adult', 'adult', 'professional']::text[], 2),
  ('food.myplate', 'physical', 'NutritionScreen', 'MyPlate', 'Build a balanced plate, with guides for every age.', 'https://www.myplate.gov', 'USDA', 'guide', 'free', array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], 3),
  ('food.nutrition-source', 'physical', 'NutritionScreen', 'The Nutrition Source', 'Research-backed answers on food and health.', 'https://nutritionsource.hsph.harvard.edu', 'Harvard T.H. Chan School of Public Health', 'article', 'free', array['teen', 'young_adult', 'adult', 'professional']::text[], 4),
  ('food.kidshealth-food', 'physical', 'NutritionScreen', 'KidsHealth: Food & Fitness', 'Eating well, explained for kids.', 'https://kidshealth.org/en/kids/center/fitness-nutrition-center.html', 'Nemours', 'article', 'free', array['kid']::text[], 5),
  ('sleep.sleep-foundation', 'physical', 'SleepRecoveryScreen', 'Sleep Foundation', 'Sleep science and practical tips, reviewed by doctors.', 'https://www.sleepfoundation.org', 'Sleep Foundation', 'article', 'free', array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], 6),
  ('sleep.cdc-sleep', 'physical', 'SleepRecoveryScreen', 'CDC: Sleep', 'How much sleep each age needs, and why it matters.', 'https://www.cdc.gov/sleep/index.html', 'CDC', 'guide', 'free', array['kid', 'teen', 'young_adult', 'adult', 'professional']::text[], 7),
  ('sleep.teens-sleep', 'physical', 'SleepRecoveryScreen', 'KidsHealth: Common Sleep Problems', 'Why teens struggle to sleep and what helps.', 'https://kidshealth.org/en/teens/sleep.html', 'Nemours', 'article', 'free', array['teen']::text[], 8),
  ('energy.myhealthfinder', 'physical', 'EnergyVitalityScreen', 'MyHealthfinder', 'Which check-ups and screenings are recommended for you.', 'https://odphp.health.gov/myhealthfinder', 'US Dept. of Health', 'tool', 'free', array['young_adult', 'adult', 'professional']::text[], 9),
